create table clientes (id int primary key, nombre text not null);
create table choferes (id int primary key, nombre text not null);
create table envios (
  id         int primary key,
  cliente_id int not null references clientes(id),
  chofer_id  int references choferes(id),   -- puede ser NULL: envío sin chofer asignado
  bultos     int not null
);
