lineas.c:
select e.id as envio, ch.id as chofer, e.chofer_id = ch.id as coincide
from envios e cross join choferes ch
order by e.id, ch.id;

select e.id as envio, ch.nombre as chofer
from envios e inner join choferes ch on ch.id = e.chofer_id
order by e.id;

select c.nombre as cliente, e.id as envio, e.bultos
from clientes c left join envios e on e.cliente_id = c.id
order by c.id, e.id;

select ch.nombre as chofer, e.id as envio
from choferes ch full join envios e on e.chofer_id = ch.id
order by ch.id, e.id;

select a.cliente_id, a.id as a, b.id as b
from envios a join envios b on b.cliente_id = a.cliente_id
order by 1, 2, 3;

select c.nombre, e.id as envio, e.bultos
from clientes c left join envios e on e.cliente_id = c.id and e.bultos > 6
order by c.id, e.id;

